const items = $input.all();

function normalizeText(value) {
  return String(value ?? "")
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+/g, " ")
    .trim();
}

function normalizeDate(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString();
}

return items.map((item) => {
  const raw = item.json;

  const rawId = raw.id ?? null;

  return {
    json: {
      // ID DB chưa có khi content mới từ WF01 đi sang WF02
      id:
        rawId === null || rawId === ""
          ? null
          : Number(rawId),

      competitor_id: Number(
        raw.competitor_id ?? raw.competitorId
      ),

      platform: normalizeText(
        raw.platform
      ).toLowerCase(),

      content_id: normalizeText(
        raw.content_id ?? raw.contentId
      ),

      title: normalizeText(
        raw.title
      ),

      description: normalizeText(
        raw.description
      ),

      url: normalizeText(
        raw.url
      ),

      published_at: normalizeDate(
        raw.published_at ?? raw.publishedAt
      ),

      // Có thì normalize, không có thì để null
      created_at: normalizeDate(
        raw.created_at ?? raw.createdAt
      )
    }
  };
});

const items = $input.all();

function cleanText(value) {
  return String(value ?? "")
    // Chuẩn hóa non-breaking space
    .replace(/\u00A0/g, " ")

    // Loại bỏ ký tự điều khiển không cần thiết
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")

    // Chuẩn hóa xuống dòng
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")

    // Đưa xuống dòng/tab về khoảng trắng
    .replace(/\s+/g, " ")

    // Xóa khoảng trắng đầu/cuối
    .trim();
}

return items.map((item) => {
  const data = item.json;

  return {
    json: {
      id: data.id,

      competitor_id: data.competitor_id,

      platform: data.platform,

      content_id: data.content_id,

      title: cleanText(data.title),

      description: cleanText(data.description),

      url: data.url,

      published_at: data.published_at,

      created_at: data.created_at
    }
  };
});

const items = $input.all();

function isValidUrl(value) {
  if (typeof value !== "string") {
    return false;
  }

  const url = value.trim();

  return /^https?:\/\/[^\s]+$/i.test(url);
}

function isValidDate(value) {
  if (!value) {
    return false;
  }

  const date = new Date(value);

  return !Number.isNaN(date.getTime());
}

function isValidYoutubeContentId(contentId) {
  return /^[A-Za-z0-9_-]{11}$/.test(contentId);
}

return items.map((item) => {
  const data = item.json;
  const errors = [];

  // ID DB chỉ validate nếu đã tồn tại.
  // Content mới từ WF01 chưa có ID.
  if (
    data.id !== null &&
    data.id !== undefined &&
    (
      !Number.isInteger(data.id) ||
      data.id <= 0
    )
  ) {
    errors.push("id không hợp lệ");
  }

  if (
    !Number.isInteger(data.competitor_id) ||
    data.competitor_id <= 0
  ) {
    errors.push("competitor_id không hợp lệ");
  }

  if (!data.platform) {
    errors.push("platform bị thiếu");
  }

  if (!data.content_id) {
    errors.push("content_id bị thiếu");
  } else if (
    data.platform === "youtube" &&
    !isValidYoutubeContentId(data.content_id)
  ) {
    errors.push(
      "content_id YouTube không đúng định dạng"
    );
  }

  if (!data.title) {
    errors.push("title bị thiếu");
  }

  if (!isValidUrl(data.url)) {
    errors.push("url không hợp lệ");
  }

  if (!isValidDate(data.published_at)) {
    errors.push("published_at không hợp lệ");
  }

  // created_at không bắt buộc vì backend sẽ tạo khi lưu.
  if (
    data.created_at !== null &&
    data.created_at !== undefined &&
    !isValidDate(data.created_at)
  ) {
    errors.push("created_at không hợp lệ");
  }

  return {
    json: {
      ...data,
      is_valid: errors.length === 0,
      validation_errors: errors
    }
  };
});

const duplicateResults = $input.all();
const originalItems = $('07 - IF Valid').all();

if (duplicateResults.length !== originalItems.length) {
  throw new Error(
    `Số lượng item không khớp: Duplicate Check=${duplicateResults.length}, Original=${originalItems.length}`
  );
}

return duplicateResults.map((item, index) => {
  const original = originalItems[index]?.json;

  if (!original) {
    throw new Error(`Không tìm thấy content gốc tại index ${index}`);
  }

  return {
    json: {
      ...original,

      duplicate_check_success: item.json.success === true,
      exists: item.json.exists === true
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  return {
    json: {
      content_id: data.content_id ?? null,
      title: data.title ?? "",
      platform: data.platform ?? null,

      processing_status: "ignored_invalid",

      validation_errors: data.validation_errors ?? []
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  return {
    json: {
      content_id: data.content_id ?? null,
      title: data.title ?? "",
      platform: data.platform ?? null,

      processing_status: "ignored_duplicate",

      exists: data.exists === true
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const response = item.json ?? {};
  const data = response.data ?? {};

  const contentId = data.contentId ?? data.content_id ?? null;

  if (response.success !== true || !contentId) {
    throw new Error(
      'Không nhận được contentId hợp lệ từ API lưu nội dung mới'
    );
  }

  return {
    json: {
      content_id: String(contentId),
      title: data.title ?? '',
      platform: data.platform ?? 'youtube',
      processing_status: 'saved_new',
      exists: true,
      social_content_id: data.id ?? null
    }
  };
});
